CREATE OR REPLACE FUNCTION public.finance_schedule_cancel(t uuid,ident uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q finance_entry_drafts;BEGIN IF NOT finance_schedule_manager(t) THEN RAISE EXCEPTION 'Owner or admin required';END IF;PERFORM pg_advisory_xact_lock(hashtextextended('schedule:'||t::text,0));SELECT * INTO q FROM finance_entry_drafts WHERE id=ident AND tenant_id=t AND status='waiting' FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Waiting draft required';END IF;UPDATE finance_entry_drafts SET status='cancelled' WHERE id=q.id;IF q.kind IN('asset_opening','asset_acquisition','asset_reclassification') THEN UPDATE fixed_assets SET status='disposed',notes='Cancelled proposal; no journal posted' WHERE id=(q.source_data->>'asset')::uuid AND tenant_id=t;END IF;IF q.kind='prepayment_funding' THEN UPDATE prepaid_schedules SET status='cancelled' WHERE id=(q.source_data->>'schedule')::uuid AND tenant_id=t;END IF;INSERT INTO audit_log(tenant_id,user_id,action,entity_type,entity_id) VALUES(t,auth.uid(),'finance_draft_cancelled','finance_entry_drafts',q.id::text);END $$;
REVOKE ALL ON FUNCTION public.finance_schedule_cancel(uuid,uuid) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.finance_schedule_cancel(uuid,uuid) TO authenticated;
DO $$ DECLARE def text;BEGIN
SELECT pg_get_functiondef('public.finance_schedule_enqueue(uuid,date,text,text,text,text,jsonb,jsonb,text,uuid)'::regprocedure) INTO def;
def:=replace(def,'ON CONFLICT(tenant_id,source_key) DO NOTHING RETURNING id INTO ident','ON CONFLICT(tenant_id,source_key) DO UPDATE SET entry_date=excluded.entry_date,kind=excluded.kind,label=excluded.label,reason=excluded.reason,lines=excluded.lines,source_data=excluded.source_data,source_document=excluded.source_document,linked_entry_id=excluded.linked_entry_id,status=''waiting'',created_by=excluded.created_by,created_at=now() WHERE finance_entry_drafts.status=''cancelled'' RETURNING id INTO ident');EXECUTE def;
SELECT pg_get_functiondef('public.finance_schedule_prepare(uuid,date)'::regprocedure) INTO def;
def:=replace(def,'jsonb_build_object(''asset'',a.id,''amount'',amt,''expected_depreciated'',a.amount_depreciated)','jsonb_build_object(''asset'',a.id,''amount'',amt,''expected_depreciated'',a.amount_depreciated,''check_kind'',''asset'',''check_id'',a.id,''fingerprint'',md5(finance_schedule_source(t,''asset'',a.id)::text))');EXECUTE def;
SELECT pg_get_functiondef('public.expense_prepaid_release(uuid)'::regprocedure) INTO def;
def:=replace(def,'IF auth.uid() IS NULL THEN','IF s.funding_draft_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM finance_entry_drafts WHERE id=s.funding_draft_id AND tenant_id=s.tenant_id AND status=''approved'' AND journal_entry_id=s.initial_journal_entry_id) THEN RAISE EXCEPTION ''Approve prepaid funding first'';END IF;IF auth.uid() IS NULL THEN');
def:=replace(def,'NOT(public.has_role(auth.uid(),''admin'') OR public.has_role(auth.uid(),''manager''))','NOT(public.finance_schedule_manager(s.tenant_id) OR public.has_role(auth.uid(),''manager''))');EXECUTE def;
END $$;
CREATE OR REPLACE FUNCTION public.finance_schedule_stock_wake() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF NEW.status='approved' AND OLD.status IS DISTINCT FROM 'approved' AND NEW.count_type='full' AND NEW.count_date=(date_trunc('month',NEW.count_date)+interval '1 month -1 day')::date AND NEW.count_date<=(now() AT TIME ZONE 'Asia/Hong_Kong')::date AND finance_schedule_manager(NEW.tenant_id) AND EXISTS(SELECT 1 FROM finance_schedule_settings WHERE tenant_id=NEW.tenant_id AND stock_basis='counts') THEN PERFORM finance_schedule_prepare_sources(NEW.tenant_id,NEW.count_date);END IF;RETURN NEW;END $$;
CREATE TRIGGER finance_schedule_stock_wake AFTER UPDATE OF status ON public.stock_count_sessions FOR EACH ROW EXECUTE FUNCTION public.finance_schedule_stock_wake();